/**
 * Config plugin: no Android auto-backup, ever.
 *
 * WHY
 * ===
 * Android auto-backup restored a whole earlier copy of the app data directory on
 * reinstall — the kv-store that holds the bot list and each bot profile, plus the
 * SQLite database — so a bot the user had DELETED came back with the next install
 * (*"in each installation i delete it and i find it in the next one like i didnt
 * delete it"*).
 *
 * `android/` is generated by `expo prebuild` and is gitignored, so the manifest
 * edit alone would be lost on the next prebuild. This plugin applies the same
 * three settings there, and writes the Android 12+ extraction rules that exclude
 * every domain.
 *
 * Nothing in this app needs restoring: games, bots and progress are derived from
 * a Lichess account or a file the user can import again. A fresh install is
 * expected to be fresh.
 */

const { withAndroidManifest, withDangerousMod } = require('@expo/config-plugins');
const fs = require('node:fs');
const path = require('node:path');

const RULES = `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/with-no-backup.js — see the plugin's header. -->
<data-extraction-rules>
  <cloud-backup>
    <exclude domain="root" />
    <exclude domain="file" />
    <exclude domain="database" />
    <exclude domain="sharedpref" />
    <exclude domain="external" />
  </cloud-backup>
  <device-transfer>
    <exclude domain="root" />
    <exclude domain="file" />
    <exclude domain="database" />
    <exclude domain="sharedpref" />
    <exclude domain="external" />
  </device-transfer>
</data-extraction-rules>
`;

function withNoBackup(config) {
  config = withAndroidManifest(config, (cfg) => {
    const app = cfg.modResults.manifest.application?.[0];
    if (app) {
      app.$ = app.$ || {};
      app.$['android:allowBackup'] = 'false';
      app.$['android:fullBackupContent'] = 'false';
      app.$['android:dataExtractionRules'] = '@xml/data_extraction_rules';
    }
    return cfg;
  });

  config = withDangerousMod(config, [
    'android',
    async (cfg) => {
      const resDir = path.join(
        cfg.modRequest.platformProjectRoot,
        'app', 'src', 'main', 'res', 'xml',
      );
      fs.mkdirSync(resDir, { recursive: true });
      fs.writeFileSync(path.join(resDir, 'data_extraction_rules.xml'), RULES, 'utf8');
      return cfg;
    },
  ]);

  return config;
}

module.exports = withNoBackup;